inventory.source:
const kind = {weapon: "weapon", armor: "armor", gear: "gear"}[args.slot ?? "all"] ?? "all";
const all = await tools.destiny_items({kind, max_chars: 3500000});
if (all.too_large) throw new Error("物品列表超过上限");
const q = (args.query ?? "").trim().toLowerCase();
let alias = new Set();
if (q) {
  const found = await max.raw("destiny_lookup", {kind: "item", search: args.query, limit: 50});
  if (found.outcome === "succeeded") alias = new Set(found.value.results.map(r => r.hash));
}
const type = (args.type ?? "").trim();
const perks = (args.perks ?? []).map(p => p.trim().toLowerCase()).filter(Boolean);
const perkMatch = item => perks.map(p => {
  for (const column of item.perks ?? []) {
    const index = column.findIndex(name => name.toLowerCase().includes(p));
    if (index >= 0) return {perk: column[index], slotted: index === 0};
  }
  return null;
});
const hits = all.items.filter(item =>
  (!q || (item.name ?? "").toLowerCase().includes(q) || alias.has(item.hash)) &&
  (!type || (item.type ?? "").includes(type)) &&
  (!perks.length || perkMatch(item).every(Boolean)));
hits.sort((a, b) => (a.name ?? "").localeCompare(b.name ?? "") || (b.power ?? 0) - (a.power ?? 0));
const limit = Math.min(args.limit ?? 30, 60);
const where = {vault: "仓库", account: "账号", inventory: "背包", equipped: "已装备", postmaster: "邮政官"};
const rows = hits.slice(0, limit).map(item => {
  const out = {name: item.name, type: item.type, tier: item.tier, hash: item.hash, item_id: item.id, location: (item.character ?? "") + where[item.location], character_id: item.character_id ?? null, equipped: item.location === "equipped"};
  for (const key of ["quantity", "power", "damage", "locked", "masterwork", "crafted", "enhanced"]) if (item[key] !== undefined) out[key] = item[key];
  if (perks.length) { out.perk_match = perkMatch(item); out.perk_columns = item.perks; }
  else if (args.with_perks !== false && item.perks) out.perks = item.perks.map(column => column[0]);
  if (args.with_stats && item.stats) out.stats = item.stats;
  return out;
});
return {bungie_name: all.bungie_name, minted: all.minted, total_items: all.count, matched: hits.length, shown: rows.length, matches: rows};

move.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {ok: false, error: acct.login, steps: []};
const mt = acct.membership_type, mid = acct.membership_id;
const base = `/Destiny2/${mt}/Profile/${mid}/`;
const cls = {};
for (const c of acct.characters) cls[c.character_id] = c.class;
const target = args.to === "vault" ? null : args.to;
if (target !== null && !(target in cls)) return {ok: false, error: "to 必须是 \"vault\" 或你自己的 character_id", steps: []};
if (args.equip && target === null) return {ok: false, error: "仓库里不能装备；equip 需要目标角色", steps: []};
const place = owner => owner === null ? "仓库" : cls[owner] ?? owner;
// Where the item is now. Profile reads can be minutes old (Bungie caches by
// URL), so writes locate the single item with a fresh read.
const locate = async () => {
  const r = await max.raw("destiny_read", {path: `${base}Item/${args.item_id}/`, query: {components: [300, 307]}, fresh: true});
  if (r.outcome !== "succeeded" || !r.value.item?.data) return null;
  const item = r.value.item.data;
  return {item, owner: r.value.characterId ?? null, equipped: r.value.instance?.data?.isEquipped === true, postmaster: item.location === 4};
};
const steps = [];
const act = async (label, action, body) => {
  const r = await max.raw("destiny_write", {path: `/Destiny2/Actions/Items/${action}/`, body: {...body, membershipType: mt}});
  const ok = r.outcome === "committed" || r.outcome === "succeeded";
  steps.push(ok ? {step: label, ok} : {step: label, ok, outcome: r.outcome, error: r.error?.message});
  return ok;
};
const plan = async found => {
  const it = found.item;
  const transfer = (toVault, cid) => act(toVault ? `从${place(cid)}放进仓库` : `从仓库取到${place(cid)}`, "TransferItem", {itemReferenceHash: it.itemHash, stackSize: it.quantity ?? 1, transferToVault: toVault, itemId: args.item_id, characterId: cid});
  const equip = cid => act(`给${place(cid)}装备`, "EquipItem", {itemId: args.item_id, characterId: cid});
  if (found.owner === target) return !args.equip || found.equipped || await equip(target);
  if (found.equipped) {
    // An equipped item cannot move: equip another from the same slot first, preferring non-exotics.
    const inv = await tools.destiny_read({path: `${base}Character/${found.owner}/`, query: {components: [201]}, max_chars: 3500000, fresh: true});
    const candidates = (inv.inventory?.data?.items ?? []).filter(x => x.bucketHash === it.bucketHash && x.itemInstanceId);
    if (!candidates.length) { steps.push({step: `${place(found.owner)}同栏位没有能换上的物品`, ok: false}); return false; }
    const defs = (await tools.destiny_lookup({kind: "item", hashes: [...new Set(candidates.map(x => x.itemHash))]})).definitions;
    candidates.sort((a, b) => ((defs[a.itemHash]?.tierType === 6) - (defs[b.itemHash]?.tierType === 6)));
    const swap = candidates[0];
    if (!await act(`先给${place(found.owner)}换上「${defs[swap.itemHash]?.name ?? swap.itemHash}」`, "EquipItem", {itemId: swap.itemInstanceId, characterId: found.owner})) return false;
  }
  if (found.owner !== null && !await transfer(true, found.owner)) return false;
  if (target !== null && !await transfer(false, target)) return false;
  return !args.equip || target === null || await equip(target);
};
let found = await locate();
if (!found) return {ok: false, error: "找不到这个 item_id（可能已被分解，或 id 抄错了）", steps};
if (found.postmaster) return {ok: false, error: "物品在邮政官里，先用 PullFromPostmaster 取到角色身上", from: place(found.owner), steps};
const from = place(found.owner) + (found.equipped ? "（已装备）" : "");
let done = await plan(found);
// A refused step usually means the item was not where the read said; locate
// it again and try once more from where it really is.
if (!done && steps.some(s => s.ok === false && /ItemNotFound|NotFound|ItemNotTransferrable|CannotPerformAction/i.test(s.error ?? ""))) {
  found = await locate();
  if (found && !found.postmaster) done = await plan(found);
}
const after = await locate();
const verified = Boolean(after) && after.owner === target && (!args.equip || after.equipped);
return {ok: done && verified, verified, item_id: args.item_id, from, to: place(target) + (args.equip ? "（装备）" : ""), now: after ? place(after.owner) + (after.equipped ? "（已装备）" : "") : "未知", steps};

recent.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login, activities: []};
const mt = acct.membership_type, mid = acct.membership_id;
const chars = args.character_id ? acct.characters.filter(c => c.character_id === args.character_id) : acct.characters;
if (!chars.length) return {linked: true, error: "没有匹配的角色", activities: []};
const count = Math.min(args.count ?? 10, 25);
const pages = await Promise.all(chars.map(c => max.raw("destiny_read", {path: `/Destiny2/${mt}/Account/${mid}/Character/${c.character_id}/Stats/Activities/`, query: {count, mode: args.mode ?? 0, page: 0}})));
const rows = [], errors = [];
pages.forEach((page, i) => {
  if (page.outcome !== "succeeded") errors.push({class: chars[i].class, error: page.error?.message});
  else for (const a of page.value.activities ?? []) rows.push({c: chars[i], a});
});
rows.sort((x, y) => y.a.period.localeCompare(x.a.period));
const shown = rows.slice(0, count);
const hashes = [...new Set(shown.flatMap(r => [r.a.activityDetails.referenceId, r.a.activityDetails.directorActivityHash]).filter(Boolean))];
const names = hashes.length ? (await tools.destiny_lookup({kind: "activity", hashes})).definitions : {};
const modes = {2: "剧情", 3: "打击", 4: "突袭", 5: "PvP", 6: "巡逻", 7: "PvE", 10: "占领", 12: "冲突", 18: "打击", 19: "铁旗", 25: "混战", 46: "宗师/日落", 48: "混战", 63: "智谋", 69: "竞技", 70: "快速比赛", 82: "地牢", 84: "试炼", 87: "失落区域"};
const value = (a, key) => a.values?.[key]?.basic?.value;
const display = (a, key) => a.values?.[key]?.basic?.displayValue;
return {
  bungie_name: acct.bungie_name,
  activities: shown.map(({c, a}) => {
    const d = a.activityDetails;
    const out = {
      time: a.period, class: c.class,
      activity: names[d.directorActivityHash]?.name ?? names[d.referenceId]?.name ?? String(d.referenceId),
      mode: modes[d.mode] ?? `mode ${d.mode}`,
      completed: value(a, "completed") === 1,
      kills: value(a, "kills"), deaths: value(a, "deaths"), assists: value(a, "assists"),
      kd: display(a, "killsDeathsRatio"), duration: display(a, "timePlayedSeconds"),
      instance_id: d.instanceId
    };
    const standing = display(a, "standing");
    if (standing) out.standing = standing;
    return out;
  }),
  errors
};

pgcr.source:
const report = await tools.destiny_read({path: `/Destiny2/Stats/PostGameCarnageReport/${args.instance_id}/`, max_chars: 3500000});
if (report.too_large) throw new Error("PGCR 响应超过上限");
const account = await max.raw("destiny_account", {});
const me = account.outcome === "succeeded" && account.value.linked ? account.value.membership_id : null;
const value = (values, key) => values?.[key]?.basic?.value;
const display = (values, key) => values?.[key]?.basic?.displayValue;
const entries = report.entries ?? [];
const details = report.activityDetails ?? {};
const weaponHashes = entries.flatMap(e => (e.extended?.weapons ?? []).map(w => w.referenceId));
const activityHashes = [details.directorActivityHash, details.referenceId].filter(Boolean);
const [weapons, activities] = await Promise.all([
  weaponHashes.length ? tools.destiny_lookup({kind: "item", hashes: [...new Set(weaponHashes)].slice(0, 500)}) : {definitions: {}},
  activityHashes.length ? tools.destiny_lookup({kind: "activity", hashes: [...new Set(activityHashes)]}) : {definitions: {}}
]);
const classes = {3655393761: "泰坦", 671679327: "猎人", 2271682572: "术士"};
const modes = {2: "剧情", 3: "打击", 4: "突袭", 5: "PvP", 6: "巡逻", 7: "PvE", 10: "占领", 12: "冲突", 18: "打击", 19: "铁旗", 25: "混战", 46: "宗师/日落", 48: "混战", 63: "智谋", 69: "竞技", 70: "快速比赛", 82: "地牢", 84: "试炼", 87: "失落区域"};
const name = info => info?.bungieGlobalDisplayName ? `${info.bungieGlobalDisplayName}#${String(info.bungieGlobalDisplayNameCode ?? 0).padStart(4, "0")}` : (info?.displayName ?? "?");
const players = entries.map(e => {
  const info = e.player?.destinyUserInfo ?? {};
  const ext = e.extended?.values ?? {};
  const out = {
    name: name(info),
    class: classes[e.player?.classHash] ?? e.player?.characterClass,
    light: e.player?.lightLevel,
    kills: value(e.values, "kills"), deaths: value(e.values, "deaths"), assists: value(e.values, "assists"),
    kd: display(e.values, "killsDeathsRatio"),
    completed: value(e.values, "completed") === 1,
    time_played: display(e.values, "timePlayedSeconds"),
    weapons: (e.extended?.weapons ?? [])
      .map(w => ({name: weapons.definitions[w.referenceId]?.name ?? String(w.referenceId), kills: value(w.values, "uniqueWeaponKills") ?? 0, precision: value(w.values, "uniqueWeaponPrecisionKills") ?? 0}))
      .sort((a, b) => b.kills - a.kills).slice(0, 3),
    abilities: {grenade: value(ext, "weaponKillsGrenade") ?? 0, melee: value(ext, "weaponKillsMelee") ?? 0, super: value(ext, "weaponKillsSuper") ?? 0}
  };
  if (me && info.membershipId === me) out.me = true;
  if (value(e.values, "team") !== undefined) out.team = value(e.values, "team");
  if (display(e.values, "standing")) out.standing = display(e.values, "standing");
  if (value(e, "score") !== undefined && value(e, "score") !== 0) out.score = value(e, "score");
  return out;
}).sort((a, b) => (b.kills ?? 0) - (a.kills ?? 0)).slice(0, args.max_players ?? 12);
const first = entries[0]?.values ?? {};
return {
  instance_id: args.instance_id,
  period: report.period,
  activity: activities.definitions[details.directorActivityHash]?.name ?? activities.definitions[details.referenceId]?.name ?? String(details.referenceId),
  mode: modes[details.mode] ?? `mode ${details.mode}`,
  duration: display(first, "activityDurationSeconds"),
  from_beginning: report.activityWasStartedFromBeginning,
  completed: players.some(p => p.completed),
  player_count: entries.length,
  teams: (report.teams ?? []).map(t => ({team: t.teamId, name: t.teamName, standing: display(t, "standing") ?? t.standing?.basic?.displayValue, score: t.score?.basic?.value})),
  players
};

loadout.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login};
const mt = acct.membership_type, mid = acct.membership_id;
const pick = args.character_id ? acct.characters.find(c => c.character_id === args.character_id)
  : args.class ? acct.characters.find(c => c.class === args.class) : acct.characters[0];
if (!pick) return {error: "没有匹配的角色", characters: acct.characters.map(c => ({character_id: c.character_id, class: c.class}))};
const r = await tools.destiny_read({path: `/Destiny2/${mt}/Profile/${mid}/Character/${pick.character_id}/`, query: {components: [200, 205, 300, 304, 305]}, max_chars: 3500000});
if (r.too_large) throw new Error("角色响应超过上限");
const define = async (kind, hashes, into) => {
  const todo = [...new Set(hashes.filter(h => h && !(h in into)))];
  for (let i = 0; i < todo.length; i += 500) Object.assign(into, (await tools.destiny_lookup({kind, hashes: todo.slice(i, i + 500)})).definitions);
};
const equipped = r.equipment?.data?.items ?? [];
const inst = r.itemComponents?.instances?.data ?? {};
const sockets = r.itemComponents?.sockets?.data ?? {};
const itemStats = r.itemComponents?.stats?.data ?? {};
const defs = {}, buckets = {}, categories = {}, plugs = {}, stats = {};
await define("item", equipped.map(i => i.itemHash), defs);
// Weapons (3), armor (2) and the subclass (16); emblems, ships and the like are cosmetic.
const gear = equipped.filter(i => [2, 3, 16].includes(defs[i.itemHash]?.itemType));
// Shaders and ornaments live in the cosmetic socket categories.
const cosmetic = new Set([2048875504, 1926152773]);
const live = item => (defs[item.itemHash].sockets ?? [])
  .filter(s => s.category && !cosmetic.has(s.category))
  .map(s => ({category: s.category, plug: sockets[item.itemInstanceId]?.sockets?.[s.index]}))
  .filter(s => s.plug?.plugHash && s.plug.isVisible !== false);
await Promise.all([
  define("bucket", gear.map(i => i.bucketHash), buckets),
  define("socketcategory", gear.flatMap(i => live(i).map(s => s.category)), categories),
  define("item", gear.flatMap(i => live(i).map(s => s.plug.plugHash)), plugs),
  define("stat", Object.keys(r.character?.data?.stats ?? {}).map(Number).concat(gear.flatMap(i => Object.keys(itemStats[i.itemInstanceId]?.stats ?? {}).map(Number))), stats)
]);
const damage = {1: "动能", 2: "电弧", 3: "烈日", 4: "虚空", 6: "冰影", 7: "缚丝"};
const named = (table, hash) => table[hash]?.name ?? String(hash);
const rows = gear.map(item => {
  const d = defs[item.itemHash], i = inst[item.itemInstanceId] ?? {};
  const grouped = {};
  for (const s of live(item)) {
    const name = plugs[s.plug.plugHash]?.name;
    if (!name) continue;
    (grouped[named(categories, s.category)] ??= []).push(name);
  }
  const out = {slot: named(buckets, item.bucketHash), name: d.name, type: d.type, tier: d.tier, item_id: item.itemInstanceId};
  if (i.primaryStat?.value > 0) out.power = i.primaryStat.value;
  if (damage[i.damageType]) out.damage = damage[i.damageType];
  if (Object.keys(grouped).length) out.sockets = grouped;
  if (d.itemType === 2 && itemStats[item.itemInstanceId]) {
    out.stats = Object.fromEntries(Object.values(itemStats[item.itemInstanceId].stats).filter(s => s.value).map(s => [named(stats, s.statHash), s.value]));
  }
  return out;
});
return {
  bungie_name: acct.bungie_name,
  character: {character_id: pick.character_id, class: pick.class, light: r.character?.data?.light ?? pick.light, last_played: pick.last_played},
  stats: Object.fromEntries(Object.entries(r.character?.data?.stats ?? {}).map(([h, v]) => [named(stats, h), v])),
  gear: rows
};

career.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login};
const mt = acct.membership_type, mid = acct.membership_id;
const r = await tools.destiny_read({path: `/Destiny2/${mt}/Account/${mid}/Stats/`, max_chars: 3500000});
if (r.too_large) throw new Error("生涯统计响应超过上限");
const weaponNames = {AutoRifle: "自动步枪", BeamRifle: "追踪步枪", Bow: "战斗弓", Glaive: "偃月", FusionRifle: "融合步枪", HandCannon: "手炮", TraceRifle: "追踪步枪", MachineGun: "机枪", PulseRifle: "脉冲步枪", RocketLauncher: "火箭发射器", ScoutRifle: "斥候步枪", Shotgun: "霰弹枪", Sniper: "狙击步枪", Submachinegun: "微型冲锋枪", Relic: "遗物", SideArm: "手枪", Sword: "剑", GrenadeLauncher: "榴弹发射器", Ability: "技能", Grenade: "手雷", Super: "超能", Melee: "近战"};
const shown = (bucket, keys) => Object.fromEntries(keys.filter(k => bucket?.[k]).map(k => [k, bucket[k].basic.displayValue]));
const topWeapons = bucket => Object.entries(bucket ?? {})
  .filter(([k, v]) => k.startsWith("weaponKills") && v.basic?.value > 0)
  .sort((a, b) => b[1].basic.value - a[1].basic.value).slice(0, 6)
  .map(([k, v]) => ({type: weaponNames[k.slice(11)] ?? k.slice(11), kills: v.basic.value}));
const summary = (results, perCharacter) => {
  const pve = results?.allPvE?.allTime, pvp = results?.allPvP?.allTime;
  const out = {};
  if (pve) {
    out.pve = shown(pve, perCharacter ? ["activitiesCleared", "kills", "deaths", "killsDeathsRatio", "secondsPlayed"] : ["activitiesCleared", "activitiesEntered", "kills", "deaths", "assists", "killsDeathsRatio", "efficiency", "precisionKills", "secondsPlayed", "bestSingleGameKills", "longestKillSpree", "publicEventsCompleted", "heroicPublicEventsCompleted", "resurrectionsPerformed", "orbsDropped", "suicides"]);
    if (!perCharacter) out.pve_top_weapons = topWeapons(pve);
  }
  if (pvp) {
    out.pvp = shown(pvp, perCharacter ? ["activitiesEntered", "activitiesWon", "killsDeathsRatio", "secondsPlayed"] : ["activitiesEntered", "activitiesWon", "kills", "deaths", "assists", "killsDeathsRatio", "killsDeathsAssists", "efficiency", "combatRating", "winLossRatio", "precisionKills", "secondsPlayed", "bestSingleGameKills", "longestKillSpree"]);
    const entered = pvp.activitiesEntered?.basic?.value, won = pvp.activitiesWon?.basic?.value;
    if (entered) out.pvp.win_rate = `${Math.round(100 * (won ?? 0) / entered)}%`;
    if (!perCharacter) out.pvp_top_weapons = topWeapons(pvp);
  }
  return out;
};
const classOf = Object.fromEntries(acct.characters.map(c => [c.character_id, c.class]));
return {
  bungie_name: acct.bungie_name,
  ...summary(r.mergedAllCharacters?.results, false),
  characters: (r.characters ?? []).filter(c => !c.deleted).map(c => ({character_id: c.characterId, class: classOf[c.characterId] ?? "未知", ...summary(c.results, true)}))
};

weekly.source:
const lookup = async (kind, hashes) => {
  const u = [...new Set(hashes.filter(Boolean))], out = {};
  for (let i = 0; i < u.length; i += 500) Object.assign(out, (await tools.destiny_lookup({kind, hashes: u.slice(i, i + 500)})).definitions);
  return out;
};
const [milestones, vendors] = await Promise.all([
  tools.destiny_read({path: "/Destiny2/Milestones/", max_chars: 3500000}),
  max.raw("destiny_read", {path: "/Destiny2/Vendors/", query: {components: [400, 402]}, max_chars: 3500000})
]);
const weekly = Object.values(milestones).filter(m => m.activities?.length);
const [ms, acts, mods] = await Promise.all([
  lookup("milestone", weekly.map(m => m.milestoneHash)),
  lookup("activity", weekly.flatMap(m => m.activities.map(a => a.activityHash))),
  lookup("modifier", weekly.flatMap(m => m.activities.flatMap(a => a.modifierHashes ?? [])))
]);
const types = await lookup("activitytype", Object.values(acts).map(a => a.activityTypeHash));
const kindOf = a => {
  const type = types[a?.activityTypeHash]?.name;
  if (type === "突袭" || a?.modeTypes?.includes(4)) return "突袭";
  if (type === "地牢" || a?.modeTypes?.includes(82)) return "地牢";
  return type ?? "其他";
};
// Exotic drop bonuses are per player ({var:…} in the text); challenges are
// modifiers whose text names a challenge; the rest (shields, champions) apply.
const rows = weekly.map(m => {
  const versions = m.activities.map(a => acts[a.activityHash]?.name?.split(/[:：]/)[1]?.trim()).filter(Boolean);
  const challenges = new Set(), modifiers = new Set();
  for (const h of m.activities.flatMap(a => a.modifierHashes ?? [])) {
    const d = mods[h];
    if (!d?.name || (d.description ?? "").includes("{var:")) continue;
    (/挑战/.test(d.description ?? "") || /挑战/.test(d.name) ? challenges : modifiers).add(d.name);
  }
  const first = acts[m.activities[0].activityHash];
  const row = {kind: kindOf(first), name: ms[m.milestoneHash]?.name ?? first?.name?.split(/[:：]/)[0] ?? String(m.milestoneHash)};
  // A weekly challenge objective marks the featured (pinnacle) raids this week.
  if (m.activities.some(a => a.challengeObjectiveHashes?.length)) row.weekly_challenge = true;
  if (versions.length) row.versions = [...new Set(versions)];
  if (challenges.size) row.challenges = [...challenges];
  if (modifiers.size) row.modifiers = [...modifiers];
  return row;
});
rows.sort((a, b) => (b.weekly_challenge ? 1 : 0) - (a.weekly_challenge ? 1 : 0) || a.kind.localeCompare(b.kind));
const xurHash = 2190858386;
let xur = {present: false};
if (vendors.outcome === "succeeded" && vendors.value.vendors?.data?.[xurHash]) {
  const sales = Object.values(vendors.value.sales?.data?.[xurHash]?.saleItems ?? {});
  const names = await lookup("item", sales.flatMap(s => [s.itemHash, ...(s.costs ?? []).map(c => c.itemHash)]));
  const classes = {0: "泰坦", 1: "猎人", 2: "术士"};
  xur = {
    present: true,
    leaves: vendors.value.vendors.data[xurHash].nextRefreshDate,
    items: [...new Map(sales.filter(s => names[s.itemHash]?.name && names[s.itemHash]?.type).map(s => {
      const d = names[s.itemHash];
      const item = {name: d.name, type: d.type, tier: d.tier};
      if (classes[d.classType]) item.class = classes[d.classType];
      const cost = (s.costs ?? []).filter(c => c.quantity).map(c => `${names[c.itemHash]?.name ?? c.itemHash}×${c.quantity}`).join("、");
      if (cost) item.cost = cost;
      return [JSON.stringify(item), item];
    })).values()]
  };
} else if (vendors.outcome !== "succeeded") xur = {present: null, error: vendors.error?.message ?? vendors.outcome};
const ends = weekly.map(m => m.endDate).find(Boolean) ?? null;
return {resets: ends, activities: rows, xur};

raids.source:
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login};
const mt = acct.membership_type, mid = acct.membership_id;
const lookup = async (kind, hashes) => {
  const u = [...new Set(hashes.filter(Boolean))], out = {};
  for (let i = 0; i < u.length; i += 500) Object.assign(out, (await tools.destiny_lookup({kind, hashes: u.slice(i, i + 500)})).definitions);
  return out;
};
const [aggregates, progress] = await Promise.all([
  Promise.all(acct.characters.map(c => max.raw("destiny_read", {path: `/Destiny2/${mt}/Account/${mid}/Character/${c.character_id}/Stats/AggregateActivityStats/`, max_chars: 3500000}))),
  max.raw("destiny_read", {path: `/Destiny2/${mt}/Profile/${mid}/`, query: {components: [202]}, max_chars: 3500000, fresh: true})
]);
const rows = [];
aggregates.forEach((r, i) => {
  if (r.outcome === "succeeded") for (const a of r.value.activities ?? []) rows.push({c: acct.characters[i], a});
});
const perCharacter = progress.outcome === "succeeded" ? progress.value.characterProgressions?.data ?? {} : {};
const milestones = Object.entries(perCharacter).flatMap(([cid, p]) => Object.values(p.milestones ?? {}).map(m => ({cid, m})));
const acts = await lookup("activity", [...rows.map(r => r.a.activityHash), ...milestones.flatMap(({m}) => (m.activities ?? []).map(a => a.activityHash))]);
const types = await lookup("activitytype", Object.values(acts).map(a => a.activityTypeHash));
const kindOf = d => {
  const type = types[d?.activityTypeHash]?.name;
  if (type === "突袭" || d?.modeTypes?.includes(4)) return "raids";
  if (type === "地牢" || d?.modeTypes?.includes(82)) return "dungeons";
  return null;
};
// "最后一愿: 标准" and "玻璃拱顶: 大师" count toward one raid; masters are also counted apart.
const base = name => name.split(/[:：]/)[0].trim();
const master = name => /大师|宗师/.test(name.split(/[:：]/)[1] ?? "");
const out = {raids: {}, dungeons: {}};
for (const {c, a} of rows) {
  const d = acts[a.activityHash], kind = kindOf(d);
  const clears = a.values?.activityCompletions?.basic?.value ?? 0;
  if (!kind || !clears) continue;
  const name = base(d.name);
  const entry = out[kind][name] ??= {name, clears: 0, master: 0, by_class: {}, fastest: null};
  entry.clears += clears;
  if (master(d.name)) entry.master += clears;
  entry.by_class[c.class] = (entry.by_class[c.class] ?? 0) + clears;
  const fastest = a.values?.fastestCompletionMsForActivity?.basic;
  if (fastest?.value > 0 && (!entry.fastest || fastest.value < entry.fastest.ms)) entry.fastest = {ms: fastest.value, time: fastest.displayValue};
}
const finish = group => Object.values(group).sort((a, b) => b.clears - a.clears).map(e => {
  const row = {name: e.name, clears: e.clears, by_class: e.by_class, fastest: e.fastest?.time ?? null};
  if (e.master) row.master = e.master;
  return row;
});
// This week's encounters: one milestone per raid, per character; standard and
// master versions list their phases separately, so take the furthest.
const ms = await lookup("milestone", milestones.map(({m}) => m.milestoneHash));
const cls = Object.fromEntries(acct.characters.map(c => [c.character_id, c.class]));
const week = {};
for (const {cid, m} of milestones) for (const a of m.activities ?? []) {
  const d = acts[a.activityHash];
  if (!kindOf(d) || !a.phases?.length) continue;
  const name = ms[m.milestoneHash]?.name ?? base(d.name);
  const done = a.phases.filter(p => p.complete).length;
  const slot = (week[name] ??= {})[cls[cid] ?? cid];
  if (!slot || done > slot.done) week[name][cls[cid] ?? cid] = {done, total: a.phases.length};
}
const touched = Object.entries(week).filter(([, by]) => Object.values(by).some(v => v.done));
const thisWeek = touched.map(([name, by]) => ({name, by_class: Object.fromEntries(Object.entries(by).map(([k, v]) => [k, `${v.done}/${v.total}`]))}));
const untouched = Object.keys(week).filter(name => !touched.some(([n]) => n === name));
const result = {bungie_name: acct.bungie_name, raids: finish(out.raids), dungeons: finish(out.dungeons), this_week: thisWeek, this_week_untouched: untouched};
const failed = aggregates.filter(r => r.outcome !== "succeeded").length;
if (failed) result.missing_characters = failed;
if (progress.outcome !== "succeeded") result.this_week_error = progress.error?.message ?? progress.outcome;
return result;

patterns.source:
const want = args.kind ?? "patterns";
const query = (args.query ?? "").trim();
const acct = await tools.destiny_account({});
if (!acct.linked) return {linked: false, login: acct.login};
const lookup = async (kind, hashes) => {
  const u = [...new Set(hashes.filter(Boolean))], out = {};
  for (let i = 0; i < u.length; i += 500) Object.assign(out, (await tools.destiny_lookup({kind, hashes: u.slice(i, i + 500)})).definitions);
  return out;
};
const [settings, profile] = await Promise.all([
  tools.destiny_read({path: "/Settings/", max_chars: 3500000}),
  tools.destiny_read({path: `/Destiny2/${acct.membership_type}/Profile/${acct.membership_id}/`, query: {components: [900]}, max_chars: 3500000})
]);
// Patterns and catalysts hang under one presentation tree; leaves name the
// weapon type (patterns) or slot (catalysts).
const root = settings.destiny2CoreSettings?.exoticCatalystsRootNodeHash;
if (!root) throw new Error("Settings 里没有 exoticCatalystsRootNodeHash");
const leafOf = {}, parentName = {}, leaves = {};
let frontier = [root];
for (let depth = 0; frontier.length && depth < 8; depth++) {
  const nodes = await lookup("node", frontier);
  const next = [];
  for (const h of frontier) {
    const n = nodes[h];
    if (!n) continue;
    for (const c of n.children?.nodes ?? []) { parentName[c] = n.name; next.push(c); }
    if (n.children?.records?.length) leaves[h] = n.name;
    for (const r of n.children?.records ?? []) leafOf[r] = h;
  }
  frontier = next;
}
// 榴弹发射器 sits under both 特殊 and 重型: name the parent when leaves collide.
const labels = Object.values(leaves);
const label = h => labels.filter(n => n === leaves[h]).length > 1 ? `${leaves[h]}（${(parentName[h] ?? "").replace(/武器模式$/, "")}）` : leaves[h];
const records = await lookup("record", Object.keys(leafOf).map(Number));
const profileRecords = profile.profileRecords?.data?.records ?? {};
const characterRecords = Object.values(profile.characterRecords?.data ?? {}).map(c => c.records ?? {});
// Character-scoped records: the furthest character counts.
const score = e => !e ? -1 : !(e.state & 4) ? 1e9 : (e.objectives ?? []).reduce((s, o) => s + Math.min(o.progress ?? 0, o.completionValue ?? 0), 0);
const entryOf = h => profileRecords[h] ?? characterRecords.map(r => r[h]).reduce((best, e) => score(e) > score(best) ? e : best, undefined);
const isCatalyst = d => d.recordType === "异域催化" || /催化/.test(d.name);
const groups = {};
let done = 0, total = 0;
for (const [h, d] of Object.entries(records)) {
  if (!d?.name || isCatalyst(d) !== (want === "catalysts")) continue;
  if (query && !d.name.includes(query)) continue;
  const e = entryOf(h);
  const g = groups[leafOf[h]] ??= {group: label(leafOf[h]), done: 0, total: 0, in_progress: [], not_started: []};
  g.total++; total++;
  if (e && !(e.state & 4)) { g.done++; done++; if (query) (g.complete ??= []).push(d.name); continue; }
  const objectives = (e?.objectives ?? []).map(o => `${o.progress ?? 0}/${o.completionValue}`);
  const started = (e?.objectives ?? []).some(o => o.progress > 0);
  // Catalysts: hidden (8) or invisible (16) means not yet obtained.
  if (want === "catalysts" && (!e || e.state & 24)) (g.not_obtained ??= []).push(d.name);
  else (started ? g.in_progress : g.not_started).push(objectives.length ? {name: d.name, progress: objectives.join(" ")} : {name: d.name});
}
const list = Object.values(groups).map(g => {
  if (!g.in_progress.length) delete g.in_progress;
  g.not_started = g.not_started.map(x => x.name);
  if (!g.not_started.length) delete g.not_started;
  return g;
});
return {bungie_name: acct.bungie_name, kind: want, done, total, groups: list};

weapon.source:
const name = (args.name ?? "").trim();
const perk = (args.perk ?? "").trim();
const lookup = async (kind, hashes) => {
  const u = [...new Set(hashes.filter(Boolean))], out = {};
  for (let i = 0; i < u.length; i += 500) Object.assign(out, (await tools.destiny_lookup({kind, hashes: u.slice(i, i + 500)})).definitions);
  return out;
};
const hits = (await tools.destiny_lookup({kind: "item", search: name, limit: 50})).results ?? [];
const weapons = hits.filter(h => h.itemType === 3);
if (!weapons.length) return {found: false, query: name, candidates: hits.slice(0, 8).map(h => ({name: h.name, type: h.type}))};
const exact = weapons.filter(h => h.name === name || h.name_en?.toLowerCase() === name.toLowerCase());
const pool = exact.length ? exact : weapons;
// Several hashes per name: reissues, adept copies, the craftable one.
const picked = pool.slice(0, args.limit ?? 4);
const defs = await lookup("item", picked.map(h => h.hash));
const sockets = Object.values(defs).flatMap(d => d.sockets ?? []);
const [categories, plugsets, collectibles] = await Promise.all([
  lookup("socketcategory", sockets.map(s => s.category)),
  lookup("plugset", sockets.flatMap(s => [s.randomPlugSet, s.plugSet])),
  lookup("collectible", Object.values(defs).map(d => d.collectibleHash))
]);
const optionsOf = s => {
  const set = plugsets[s.randomPlugSet ?? s.plugSet];
  if (set?.plugs?.length) {
    const rolls = set.plugs.filter(([, canRoll]) => canRoll).map(([h]) => h);
    return rolls.length ? rolls : set.plugs.map(([h]) => h);
  }
  return s.plugs?.length ? s.plugs : [s.initial];
};
const columnsOf = d => (d.sockets ?? []).filter(s => categories[s.category]?.name === "武器特性");
const plugs = await lookup("item", Object.values(defs).flatMap(d => [...columnsOf(d).flatMap(optionsOf), ...(d.sockets ?? []).map(s => s.initial)]));
// Trackers, mementos and empty-socket placeholders are not perks.
const noise = p => /tracker|memento|empty/.test(p.plugCategory ?? "") || /^空.*插槽$/.test(p.name);
// Enhanced copies (tier 罕见, "强化…") collapse into the base perk.
const baseName = p => p.tierType === 3 ? p.name.replace(/^强化/, "") : p.name;
const damage = {1: "动能", 2: "电弧", 3: "烈日", 4: "虚空", 6: "冰影", 7: "缚丝"};
const ammo = {1: "主武器", 2: "特殊", 3: "重型"};
const craftable = new Set(hits.filter(h => h.itemType === 30).map(h => h.name));
const seen = new Map();
const versions = [];
const perkInfo = new Map();
for (const h of picked) {
  const d = defs[h.hash];
  if (!d) continue;
  const intrinsic = (d.sockets ?? []).map(s => plugs[s.initial]).find(p => p?.plugCategory === "intrinsics");
  const columns = columnsOf(d).map(s => {
    const names = [];
    for (const ph of optionsOf(s)) {
      const p = plugs[ph];
      if (!p?.name || noise(p)) continue;
      const n = baseName(p);
      if (!names.includes(n)) names.push(n);
      if (perk && n.includes(perk) && !perkInfo.has(n)) perkInfo.set(n, p.description ?? "");
    }
    return names;
  }).filter(c => c.length);
  const key = JSON.stringify([d.name, d.tier, columns]);
  if (seen.has(key)) { seen.get(key).hashes.push(h.hash); continue; }
  const v = {name: d.name, hashes: [h.hash], type: d.type, tier: d.tier};
  if (damage[d.damageType]) v.element = damage[d.damageType];
  if (ammo[d.ammoType]) v.ammo = ammo[d.ammoType];
  if (intrinsic) v.frame = intrinsic.name;
  if (craftable.has(d.name)) v.craftable = true;
  const source = collectibles[d.collectibleHash]?.source;
  if (source) v.source = source;
  v.columns = columns;
  if (perk) v.perk_columns = columns.flatMap((c, i) => c.some(n => n.includes(perk)) ? [i] : []);
  seen.set(key, v);
  versions.push(v);
}
const result = {query: name, versions};
if (perk) result.perks = [...perkInfo].map(([n, description]) => ({name: n, description}));
if (pool.length > picked.length) result.more_versions = pool.length - picked.length;
return result;
